const input = $json.body ?? $json;

const text = (value) =>
  value === null || value === undefined
    ? ''
    : String(value).trim();

const run_id =
  Number(input.run_id ?? 0);
const suite_code =
  text(input.suite_code);
const clinic_name =
  text(input.clinic_name);
const limit =
  Number(input.limit ?? 20);

const errors = [];

if (
  !Number.isInteger(run_id) ||
  run_id < 0
) {
  errors.push({
    field: 'run_id',
    message: 'Run ID معتبر نیست.',
  });
}

if (
  run_id === 0 &&
  !suite_code
) {
  errors.push({
    field: 'suite_code',
    message: 'در نبود Run ID، Suite Code الزامی است.',
  });
}

if (
  !Number.isInteger(limit) ||
  limit < 1 ||
  limit > 100
) {
  errors.push({
    field: 'limit',
    message: 'Limit باید بین 1 و 100 باشد.',
  });
}

return [{
  json: {
    run_id,
    suite_code,
    clinic_name,
    limit,
    validation_status:
      errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];
